  sheet: (ex, t, rows) => { const X = PRV_X.vmp.calc(ex, t); rows.push({ cells: ["Nature", "Date", "Quantité", "PU achat", "Valeur d'achat", "Sortie", "Portefeuille", "Prix de vente", "PV/MV"], style: "head" }); X.R.forEach(x => rows.push({ cells: [x.r.nat || "", frDate(x.r.date), x.r.q || "", x.r.pu || "", eurz(x.va), eurz(x.vc), eurz(x.vp), x.r.pv || "", x.pvmv == null ? "" : eurz(x.pvmv)] })); },
